// === Tab: main.js ===
/*
Magical trail shader 2

Inspired by takawo's sketch:
	https://www.openprocessing.org/sketch/853212

Author:
  Jason Labbe

Site:
  jasonlabbe3d.com

Controls:
	- Move the mouse to create particles.
	- Hold the middle mouse button to fade away particles.
*/

const MAX_TRAIL_COUNT = 30;

var colorScheme = ["#0A1B28", "#071F43", "#357D7E", "#35EEEE", "#919DF0"];
var trail = [];
var particles = [];

function setup() {
  let canvas = createCanvas(windowWidth, windowHeight);
	canvas.canvas.oncontextmenu = () => false;  // Removes right-click menu.
	noCursor();
}

function draw() {
	blendMode(BLEND);
	background(0);
	blendMode(SCREEN);

	// Trim end of trail.
	trail.push([(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);

	let removeCount = 1;
	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && mouseButton == CENTER) {
		removeCount++;
	}

	for (let i = 0; i < removeCount; i++) {
		if (trail.length == 0) {
			break;
		}

		if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) || trail.length > MAX_TRAIL_COUNT) {
			trail.splice(0, 1);
		}
	}

	// Spawn particles.
	if (trail.length > 1) {
		let mouse = new p5.Vector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
		mouse.sub((window.simulatedPMouseX !== undefined ? window.simulatedPMouseX : (typeof sub_bass_prev !== 'undefined' ? map(sub_bass_prev, 0, 1, width*0.1, width*0.9) : (typeof window.simulatedMouseX !== 'undefined' ? window.simulatedMouseX - 12 : pmouseX))), (window.simulatedPMouseY !== undefined ? window.simulatedPMouseY : (typeof percussive_prev !== 'undefined' ? map(percussive_prev, 0, 1, height, 0) : (typeof window.simulatedMouseY !== 'undefined' ? window.simulatedMouseY - 12 : pmouseY))));
		if (mouse.mag() > 5) {
			mouse.normalize();
			for (let i = 0; i < 3; i++) {
				particles.push(new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), mouse.x, mouse.y));
			}
		}
	}

	// Move and kill particles.
	for (let i = particles.length - 1; i > -1; i--) {
		particles[i].move();
		if (particles[i].vel.mag() < 0.1) {
			particles.splice(i, 1);
		}
	}

	// Draw trail.
	drawingContext.shadowColor = color(0, 125, 255);

	for (let i = 0; i < trail.length; i++) {
		let mass = i * 1.5;
		drawingContext.shadowBlur = mass;

		stroke(0);
		strokeWeight(mass);
		point(trail[i][0], trail[i][1]);
	}

	// Draw particles.
	for (let i = 0; i < particles.length; i++) {
		let p = particles[i];
		var mass = p.mass * p.vel.mag() * 0.6;

		drawingContext.shadowColor = color(colorScheme[p.colorIndex]);
		drawingContext.shadowBlur = mass;

		stroke(0);
		strokeWeight(mass);
		point(p.pos.x, p.pos.y);

		stroke(255);
		strokeWeight(mass * 0.05);
		point(p.pos.x, p.pos.y);
	}
}

// === Tab: particle.js ===
function Particle(x, y, vx, vy) {

	this.pos = new p5.Vector(x, y);
	this.vel = new p5.Vector(vx, vy);
	this.vel.mult(random(10));
	this.vel.rotate(radians(random(-25, 25)));
	this.mass = random(1, 30);
	this.airDrag = random(0.92, 0.98);
	this.colorIndex = int(random(colorScheme.length));
	this.life = 0;
	this.lifeSteps = random(-1, 1);

	this.move = function() {
		this.pos.rotate(radians(this.life * 0.002));
		this.vel.mult(this.airDrag);
		this.pos.add(this.vel);
		this.life += this.lifeSteps;
	}
}

